                    onBlur={handleBlur}
                    onChange={handleChange}
                    onKeyDown={handleKeyDown}
                    size="small"
                    slotProps={{ htmlInput: { 'aria-label': `Label for ${semanticLabel(entryKey)}` } }}
                    value={draftLabel}
